function parseThresholds(thresholdArgs?: string[]): Record<string, number> | null {
  if (!thresholdArgs || thresholdArgs.length === 0) {
    return null;
  }

  const thresholds: Record<string, number> = {};
  for (const arg of thresholdArgs) {
    const match = arg.match(/^([a-z_]+)=([0-9]*\.?[0-9]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: "${arg}". Expected format: <metric>=<number>`);
    }
    const [, metricId, valueStr] = match;
    const value = parseFloat(valueStr);
    if (isNaN(value) || value < 0 || value > 1) {
      throw new Error(`Invalid threshold value for "${metricId}": "${valueStr}". Must be a number between 0 and 1.`);
    }
    thresholds[metricId] = value;
  }
  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: Record<string, number> | null = null;
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    log.error((error as Error).message);
    const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
    console.error(`Valid metric IDs: ${validMetrics.join(', ')}`);
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && !report.passed) {
    process.exit(1);
  }
}

