export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = null
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let thresholdsResult = null;
  let passed = true;

  if (thresholds && Object.keys(thresholds).length > 0) {
    thresholdsResult = [];
    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const metricPassed = metric && typeof metric.score === 'number' && metric.score >= min;
      thresholdsResult.push({
        metric: metricId,
        min,
        score: metric?.score ?? null,
        passed: metricPassed || false
      });
      if (!metricPassed) {
        passed = false;
      }
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdsResult !== null) {
    report.passed = passed;
    report.thresholds = thresholdsResult;
  }

  return report;
}

