    expect(report.thresholds[1].metric).toBe('toxicity');
    expect(report.thresholds[1].passed).toBe(true);
  });

  it('evaluates thresholds and fails when any metric does not meet minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.99
      }
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0].passed).toBe(false);
    expect(report.thresholds[0].score).toBeLessThan(0.99);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: [],
      references: []
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.5
      }
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds[0].score).toBe(null);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('does not include thresholds when none are specified', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });
    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });
});

